import subprocess

# Example of running a safe subprocess command
def run_safe_ps_command():
    try:
        # Using a fixed command to avoid injection vulnerabilities
        result = subprocess.run(['ps', 'aux'], capture_output=True, text=True, check=True)
        print(result.stdout)
    except subprocess.CalledProcessError as e:
        print('Failed to execute ps command:', e)

run_safe_ps_command()

import subprocess

def check_ps_command():
    try:
        result = subprocess.run(['ps', 'aux'], capture_output=True, text=True, check=True)
        print("ps command output:", result.stdout)
    except subprocess.CalledProcessError as e:
        print("Failed to execute ps command:", e)

check_ps_command()
